const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate bounding box for Lake Winnipeg, Canada
  const lakeWinnipeg = ee.Geometry.Rectangle([-99.5, 50.3, -96.0, 53.8]);

  // Dates for comparison
  const date1_start = '2021-05-05'; // A few days before May 7
  const date1_end = '2021-05-09';   // A few days after May 7
  const date2_start = '2021-05-17'; // A few days before May 19
  const date2_end = '2021-05-21';   // A few days after May 19

  // Sentinel-1 parameters
  const S1_COLLECTION = 'COPERNICUS/S1_GRD';
  const POLARIZATION = 'VH'; // VH is often good for distinguishing water/ice
  const ORBIT_PROPERTY = 'DESCENDING';
  const S1_SCALE = 100; // Meters, suitable for Sentinel-1 GRD

  // Function to get and process Sentinel-1 images
  function getAndProcessS1(startDate, endDate, geometry) {
    let collection = ee.ImageCollection(S1_COLLECTION)
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', POLARIZATION))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', ORBIT_PROPERTY))
      .select(POLARIZATION);

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return null;
    }

    // Apply speckle filter and convert to dB
    const processedImage = collection.median()
      .focal_median(3) // Simple speckle filter
      .unitScale(-30, 0) // Scale to 0-1 for easier thresholding if needed, but we'll use dB
      .clamp(0, 1) // Clamp ensures values are within a reasonable range after speckle filter
      .rename('band'); // Rename for consistent band access

    return processedImage;
  }

  // Define a function to calculate ice extent
  function calculateIceExtent(image, geometry, description) {
    if (image === null) {
      console.log(`${description} images: 0.`);
      return { extent: null, pixelCount: 0 };
    }

    // Ice detection using a threshold. Open water typically has very low VH backscatter.
    // Pixels with VH backscatter above this threshold are considered "non-water" (i.e., ice or land).
    // The lake area will mostly be ice or open water.
    // -20 dB is a common threshold for water detection. Let's use -19 dB as a conservative estimate.
    const waterMask = image.lt(-19); // Pixels less than -19 dB are considered open water.

    // Invert the water mask to get ice (or non-water)
    const iceMask = waterMask.eq(0).selfMask();

    // Calculate pixel count for validation (C2)
    const icePixelCount = iceMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: S1_SCALE,
      maxPixels: 1e9
    }).get('band').getInfo();

    if (icePixelCount === 0 || icePixelCount === null) {
      console.log(`${description} images: (no valid pixels after masking).`);
      return { extent: null, pixelCount: 0 }; // No valid pixels after masking
    }

    // Calculate the area of ice pixels
    const iceAreaImage = iceMask.multiply(ee.Image.pixelArea()); // Area in m^2
    const iceExtent = iceAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: S1_SCALE,
      maxPixels: 1e9
    }).get('band').getInfo();

    console.log(`${description} images: (Val: ${iceExtent / 1e6}, Pixels: ${icePixelCount}).`);
    return { extent: iceExtent, pixelCount: icePixelCount };
  }

  // 2. Data Acquisition & Check
  const img1 = getAndProcessS1(date1_start, date1_end, lakeWinnipeg);
  const result1 = calculateIceExtent(img1, lakeWinnipeg, 'May 7, 2021 period');

  const img2 = getAndProcessS1(date2_start, date2_end, lakeWinnipeg);
  const result2 = calculateIceExtent(img2, lakeWinnipeg, 'May 19, 2021 period');

  // Check for C1 (Empty Collection)
  if (img1 === null || img2 === null) {
    console.log("Empty Collection (No images found in date/location for one or both comparison points).");
    console.log("C1");
    return;
  }

  // Check for C2 (No Valid Pixels)
  if (result1.extent === null || result2.extent === null || result1.pixelCount === 0 || result2.pixelCount === 0) {
    console.log("No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).");
    console.log("C2");
    return;
  }

  // Check for C3 (Calculation Failure - None, NaN, or invalid)
  if (result1.extent === null || isNaN(result1.extent) || result2.extent === null || isNaN(result2.extent)) {
    console.log("Calculation Failure (Result is None, NaN, or invalid).");
    console.log("C3");
    return;
  }

  // Convert to km^2 for easier comparison and printing
  const extent1_km2 = result1.extent / 1e6;
  const extent2_km2 = result2.extent / 1e6;

  console.log(`Lake ice extent May 7, 2021 period: ${extent1_km2.toFixed(2)} km^2`);
  console.log(`Lake ice extent May 19, 2021 period: ${extent2_km2.toFixed(2)} km^2`);

  // 5. Validation & Final Answer
  if (extent1_km2 > extent2_km2) {
    console.log("A"); // Yes, ice extent decreased
  } else {
    console.log("B"); // No, ice extent did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
